// Renders the Vatra app icon (1024 px, opaque, dark tile + master mark) from the brand geometry in
// VatraCore (generated by brand/scripts/emit-swift.mjs). scripts/build.sh compiles this together with the
// VatraCore sources and writes the PNG into every AppIcon.appiconset before XcodeGen runs.
import CoreGraphics
import Foundation
import ImageIO
import UniformTypeIdentifiers

func rgb(_ v: UInt32, _ a: CGFloat = 1) -> CGColor {
  CGColor(srgbRed: CGFloat(v >> 16 & 0xFF) / 255, green: CGFloat(v >> 8 & 0xFF) / 255, blue: CGFloat(v & 0xFF) / 255, alpha: a)
}

func path(_ d: String) -> CGPath {
  let p = CGMutablePath()
  for op in SVGPath.parse(d) {
    switch op {
    case .move(let x, let y): p.move(to: CGPoint(x: x, y: y))
    case .line(let x, let y): p.addLine(to: CGPoint(x: x, y: y))
    case .quad(let cx, let cy, let x, let y): p.addQuadCurve(to: CGPoint(x: x, y: y), control: CGPoint(x: cx, y: cy))
    case .cubic(let ax, let ay, let bx, let by, let x, let y): p.addCurve(to: CGPoint(x: x, y: y), control1: CGPoint(x: ax, y: ay), control2: CGPoint(x: bx, y: by))
    case .close: p.closeSubpath()
    }
  }
  return p
}

let px = 1024
let way = VatraColourway.dark
let g = VatraMarks.master
guard let ctx = CGContext(data: nil, width: px, height: px, bitsPerComponent: 8, bytesPerRow: 0, space: CGColorSpace(name: CGColorSpace.sRGB)!, bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue) else { exit(1) }
ctx.setFillColor(rgb(way.tile ?? 0x1A120D))
ctx.fill(CGRect(x: 0, y: 0, width: px, height: px))
// SVG y grows downwards
ctx.translateBy(x: 0, y: CGFloat(px))
ctx.scaleBy(x: 1, y: -1)
let b = g.bbox
let box = Double(px) * 0.62
let k = box / max(b[1] - b[0], b[3] - b[2])
ctx.translateBy(x: (Double(px) - (b[1] - b[0]) * k) / 2 - b[0] * k, y: (Double(px) - (b[3] - b[2]) * k) / 2 - b[2] * k)
ctx.scaleBy(x: k, y: k)
ctx.setLineCap(.round)
ctx.setLineJoin(.round)
ctx.setLineWidth(g.stroke)
ctx.setStrokeColor(rgb(way.line))
for d in [g.roof, g.walls] {
  ctx.addPath(path(d))
  ctx.strokePath()
}
ctx.setFillColor(rgb(way.flame))
ctx.addPath(path(g.flame))
ctx.fillPath()
if let core = g.core, let cc = way.core {
  ctx.setFillColor(rgb(cc))
  ctx.addPath(path(core))
  ctx.fillPath()
}
for (i, p) in g.puffs.enumerated() {
  ctx.setFillColor(rgb(way.line, [0.95, 0.7, 0.45][min(i, 2)]))
  ctx.fillEllipse(in: CGRect(x: p.cx - p.r, y: p.cy - p.r, width: p.r * 2, height: p.r * 2))
}
guard let img = ctx.makeImage() else { exit(1) }
for out in CommandLine.arguments.dropFirst() {
  let url = URL(fileURLWithPath: out)
  try? FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
  guard let dest = CGImageDestinationCreateWithURL(url as CFURL, UTType.png.identifier as CFString, 1, nil) else { exit(1) }
  CGImageDestinationAddImage(dest, img, nil)
  if !CGImageDestinationFinalize(dest) { exit(1) }
  print("icon \(out)")
}
